template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 58mm;
  height: 30mm;
  padding: 1.5mm 1.8mm 1.2mm;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
}
.top {
  display: flex;
  align-items: flex-start;
  gap: 1.8mm;
  min-height: 0;
}
img.product {
  flex: 0 0 auto;
  width: 10mm;
  height: 10mm;
  object-fit: cover;
  border: 0.2mm solid #111;
}
img.product[src=""] {
  display: none;
}
.info {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35mm;
}
.name {
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1.15;
  max-height: 2.3em;
  overflow: hidden;
  word-break: break-word;
}
.price-row {
  display: flex;
  align-items: baseline;
  gap: 1mm;
  margin-top: 0.2mm;
}
.price {
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1;
}
.currency {
  font-size: 9px;
  font-weight: 700;
}
.meta {
  font-size: 7px;
  line-height: 1.1;
  color: #444;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5mm;
  margin-top: 0.6mm;
  width: 100%;
}
img.barcode {
  height: 9.5mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
.code {
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.05em;
  line-height: 1;
  text-align: center;
  white-space: nowrap;
}
